@app.route("/")
def index():
    featured = books[:4]
    return render_template("index.html", books=featured, all_books=books)

@app.route("/catalog")
def catalog():
    return render_template("catalog.html", books=books)

@app.route("/book/<int:book_id>")
def book(book_id):
    selected_book = next((book for book in books if book["id"] == book_id), None)
    if not selected_book:
        return redirect(url_for("catalog"))
    return render_template("book.html", book=selected_book)

@app.route("/requests")
def requests_page():
    return render_template("requests.html")

if __name__ == "__main__":
    app.run(debug=True)
